import{_ as l,l as i,o as e,c as s,v as o,p as n,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"剂量传感闭环","description":"","frontmatter":{"title":"剂量传感闭环","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/dose-sensor-loop.md","filePath":"litho/dose-sensor-loop.md","lastUpdated":1789023840000}'),E={name:"litho/dose-sensor-loop.md"};function _(c,a,m,u,A,T){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="剂量传感闭环" tabindex="-1">剂量传感闭环 <a class="header-anchor" href="#剂量传感闭环" aria-label="Permalink to &quot;剂量传感闭环&quot;">​</a></h1><div class="epigraph"><p>脉冲能量会抖，气体会老。闭环用狭缝附近的能量计把脉冲数和衰减器扣到目标剂量，不是把激光开到最大。</p><footer>—— 对照 [剂量控制](/litho/dose-control)；扫描投影机能量传感器</footer></div><p><a href="/litho/pupil-metrology">上一课</a>校准角谱。缺口是标量：这场要多少 mJ/cm²。主干剂量课写过控制目标；本课写传感器与执行器在机台里怎么环。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开环按名义 \\(E_p\\times N\\) 会随气体寿命漂。<a href="/litho/pulse-energy-rep-rate">脉冲能量</a> 课已指出抖动。没有现场传感，CDU 的剂量项不可控。传感器脏了或标定错了，闭环会把系统偏差锁死。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>能量计放在照明路径取样位置（部分反射）。执行器：可变衰减、脉冲计数、扫描速度。每场或每扫描带修正。标定用剂量垫或剂量晶圆，把传感器读数接到胶上的有效剂量（含狭缝透过与扫描平均）。</p>',7)),(e(),n(h,null,{default:t(()=>[p(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20TGT%5B%22%E7%9B%AE%E6%A0%87%E5%89%82%E9%87%8F%22%5D%20--%3E%20CTRL%5B%22%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%0A%20%20SNS%5B%22%E8%83%BD%E9%87%8F%E8%AE%A1%22%5D%20--%3E%20CTRL%0A%20%20CTRL%20--%3E%20ATT%5B%22%E8%A1%B0%E5%87%8F%20%2F%20%E8%84%89%E5%86%B2%E6%95%B0%20%2F%20%E9%80%9F%E5%BA%A6%22%5D%0A%20%20ATT%20--%3E%20WAFER%5B%22%E6%99%B6%E5%9C%86%E5%89%82%E9%87%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p><span class="marginnote">传感器看到的是照明取样，不是胶里的化学剂量。换胶、换 BARC 不自动改闭环增益；有效剂量要重新标定。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>反馈把 \\(E_p\\) 慢漂压住。脉冲间高频抖动若快于环带宽，仍进剂量噪声——需要激光自身稳定（上一课序）。扫描速度调制可补偿狭缝向残纹，与均匀性课耦合。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课光源功率稳定：激光侧如何少给闭环添乱。传感环不能替代光瞳计。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>剂量闭环 = 能量计 + 衰减/脉冲/速度。</li><li>标定必须接到胶上的有效剂量。</li><li>出处：剂量控制课；扫描机能效通识。</li></ul>',7))])}const b=l(E,[["render",_]]);export{B as __pageData,b as default};
